def trans(g, marker, sep):
 rs=[i for i,row in enumerate(g) if all(v==sep for v in row)]
 cs=[j for j in range(len(g[0])) if all(g[i][j]==sep for i in range(len(g)))]
 rb=[]; start=0
 for x in rs+[len(g)]:
  if x>start: rb.append((start,x))
  start=x+1
 cb=[]; start=0
 for x in cs+[len(g[0])]:
  if x>start: cb.append((start,x))
  start=x+1
 return [[1 if sum(g[i][j]==marker for i in range(a,b) for j in range(c,d))==2 else 3 for c,d in cb] for a,b in rb]
